1: /* ==========================================================================
2:    Phase E3 weather surfaces, the --wx- token namespace
3:    (docs/research.md palette table, "New tokens live in a --wx- namespace
4:    next to --rp and --rv so the report and Money River files never change").
5: 
6:    The seven state tokens, one per weather state in canonical order:
7: 
8:      wx-clear     #56B4E9   sky blue (Okabe-Ito), calm and no shortfall
9:      wx-cloudy    #46617c   cloud slate, long runway with a spending gap
10:      wx-overcast  #2f4257   deep slate, the darker sibling of cloudy
11:      wx-rain      #2f7f7c   water lit, spending driven 3.0 to 11.9 months
12:      wx-drought   #d97b3f   drought orange, income covers 65 percent or less
13:      wx-storm     #ff6a4d   storm vermillion, runway under 3.0 months
14:      wx-flood     #10333f   water deep, buffer depleted or runway at 0.0
15: 
16:    Plus the two grounds every surface sits on: wx-grounds #070c18 (the
17:    archival navy, same value as --rp-void but read from its own token so
18:    this file never depends on --rp-) and wx-parchment #e9e0c9 for text.
19: 
20:    Soft tints (each state color at 26 percent over wx-grounds) carry every
21:    printed label, so measured contrast for parchment text stays above
22:    WCAG AA on all seven cells (worst case 9.3 to 1 on wx-clear-soft).
23:    Solid state colors are used for tile fills, swatches, and rules only,
24:    where no small text sits on them.
25: 
26:    Motion in this file is gated behind prefers-reduced-motion:
27:    no-preference, matching src/index.css, which also zeroes animation
28:    durations globally under prefers-reduced-motion: reduce.
29:    ========================================================================== */
30: 
31: :root {
32:   /* The seven state colors. */
33:   --wx-clear: #56b4e9;
34:   --wx-cloudy: #46617c;
35:   --wx-overcast: #2f4257;
36:   --wx-rain: #2f7f7c;
37:   --wx-drought: #d97b3f;
38:   --wx-storm: #ff6a4d;
39:   --wx-flood: #10333f;
40: 
41:   /* Grounds and text. */
42:   --wx-grounds: #070c18;
43:   --wx-parchment: #e9e0c9;
44:   --wx-rule: rgba(233, 224, 201, 0.24);
45:   --wx-text-dim: rgba(233, 224, 201, 0.74);
46:   --wx-text-faint: rgba(233, 224, 201, 0.54);
47: 
48:   /* Soft tints for any surface that prints text on a state color. */
49:   --wx-clear-soft: #1c384e;
50:   --wx-cloudy-soft: #172232;
51:   --wx-overcast-soft: #111a28;
52:   --wx-rain-soft: #112a32;
53:   --wx-drought-soft: #3e2922;
54:   --wx-storm-soft: #482426;
55:   --wx-flood-soft: #091622;
56: 
57:   /* Utility, deliberately local so nothing here reaches into --rp-. */
58:   --wx-font-display: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas,
59:     "Liberation Mono", monospace;
60:   --wx-font-body: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
61:   --wx-radius: 4px;
62: }
63: 
64: /* ==========================================================================
65:    Forecast strip: 12 month tiles, one per weather state
66:    ========================================================================== */
67: 
68: .wx-strip {
69:   display: block;
70:   width: 100%;
71: }
72: 
73: .wx-strip__svg {
74:   display: block;
75:   width: 100%;
76:   height: auto;
77: }
78: 
79: .wx-tile {
80:   fill: var(--wx-rule);
81: }
82: 
83: .wx-tile-clear {
84:   fill: var(--wx-clear);
85: }
86: 
87: .wx-tile-cloudy {
88:   fill: var(--wx-cloudy);
89: }
90: 
91: .wx-tile-overcast {
92:   fill: var(--wx-overcast);
93: }
94: 
95: .wx-tile-rain {
96:   fill: var(--wx-rain);
97: }
98: 
99: .wx-tile-drought {
100:   fill: var(--wx-drought);
101: }
102: 
103: .wx-tile-storm {
104:   fill: var(--wx-storm);
105: }
106: 
107: .wx-tile-flood {
108:   fill: var(--wx-flood);
109: }
110: 
111: .wx-strip__glyph {
112:   font-family: var(--wx-font-body);
113:   font-size: 15px;
114: }
115: 
116: .wx-strip__month {
117:   fill: var(--wx-parchment);
118:   font-family: var(--wx-font-display);
119:   font-size: 9.5px;
120:   letter-spacing: 0.06em;
121: }
122: 
123: .wx-strip__empty {
124:   fill: var(--wx-parchment);
125:   font-family: var(--wx-font-display);
126:   font-size: 11px;
127: }
128: 
129: .wx-strip__placeholder {
130:   fill: none;
131:   stroke: var(--wx-rule);
132:   stroke-dasharray: 4 4;
133: }
134: 
135: /* ==========================================================================
136:    Condition bands: the sky legend with the printed threshold sentence
137:    ========================================================================== */
138: 
139: .wx-bands {
140:   display: flex;
141:   flex-direction: column;
142:   gap: 6px;
143:   list-style: none;
144:   margin: 0;
145:   padding: 0;
146: }
147: 
148: .wx-band {
149:   display: flex;
150:   align-items: baseline;
151:   gap: 10px;
152:   padding: 8px 12px;
153:   background: var(--wx-clear-soft);
154:   border: 1px solid var(--wx-rule);
155:   border-left-width: 6px;
156:   border-radius: var(--wx-radius);
157: }
158: 
159: .wx-band-clear {
160:   background: var(--wx-clear-soft);
161:   border-left-color: var(--wx-clear);
162: }
163: 
164: .wx-band-cloudy {
165:   background: var(--wx-cloudy-soft);
166:   border-left-color: var(--wx-cloudy);
167: }
168: 
169: .wx-band-overcast {
170:   background: var(--wx-overcast-soft);
171:   border-left-color: var(--wx-overcast);
172: }
173: 
174: .wx-band-rain {
175:   background: var(--wx-rain-soft);
176:   border-left-color: var(--wx-rain);
177: }
178: 
179: .wx-band-drought {
180:   background: var(--wx-drought-soft);
181:   border-left-color: var(--wx-drought);
182: }
183: 
184: .wx-band-storm {
185:   background: var(--wx-storm-soft);
186:   border-left-color: var(--wx-storm);
187: }
188: 
189: .wx-band-flood {
190:   background: var(--wx-flood-soft);
191:   border-left-color: var(--wx-flood);
192: }
193: 
194: .wx-band-active {
195:   box-shadow: inset 0 0 0 2px var(--wx-parchment);
196: }
197: 
198: .wx-band__glyph {
199:   font-size: 1rem;
200:   color: var(--wx-parchment);
201: }
202: 
203: .wx-band__body {
204:   display: flex;
205:   flex-wrap: wrap;
206:   align-items: baseline;
207:   gap: 2px 12px;
208:   min-width: 0;
209: }
210: 
211: .wx-band__label {
212:   font-family: var(--wx-font-display);
213:   font-size: 0.8125rem;
214:   letter-spacing: 0.08em;
215:   text-transform: uppercase;
216:   color: var(--wx-parchment);
217: }
218: 
219: .wx-band__threshold {
220:   font-family: var(--wx-font-body);
221:   font-size: 0.8125rem;
222:   color: var(--wx-text-dim);
223: }
224: 
225: /* ==========================================================================
226:    EI cliff overlay: a marker line that sits over the forecast strip.
227:    The wiring view wraps the strip and this overlay in .wx-cliff-wrap,
228:    which is the positioning context (ForecastStrip lays monthCount equal
229:    width tiles across the full width, so a left percentage lands on the
230:    tile boundary the line claims).
231:    ========================================================================== */
232: 
233: .wx-cliff-wrap {
234:   position: relative;
235: }
236: 
237: .wx-cliff {
238:   position: absolute;
239:   top: 0;
240:   bottom: 0;
241:   width: 0;
242:   border-left: 2px dashed var(--wx-storm);
243:   pointer-events: none;
244:   z-index: 2;
245: }
246: 
247: .wx-cliff__label {
248:   position: absolute;
249:   top: 3px;
250:   left: 0;
251:   white-space: nowrap;
252:   padding: 1px 6px;
253:   border-radius: 2px;
254:   background: var(--wx-storm);
255:   color: var(--wx-grounds);
256:   font-family: var(--wx-font-display);
257:   font-size: 0.625rem;
258:   font-weight: 700;
259:   letter-spacing: 0.1em;
260:   text-transform: uppercase;
261: }
262: 
263: /* ==========================================================================
264:    Storm Atlas: seven count cells, state tinted, text on soft tints
265:    ========================================================================== */
266: 
267: .wx-atlas {
268:   display: flex;
269:   flex-direction: column;
270:   gap: 14px;
271: }
272: 
273: .wx-atlas__headline {
274:   margin: 0;
275:   font-family: var(--wx-font-display);
276:   font-size: 1.125rem;
277:   line-height: 1.45;
278:   letter-spacing: 0.02em;
279:   color: var(--wx-parchment);
280: }
281: 
282: .wx-atlas__note {
283:   margin: 0;
284:   font-family: var(--wx-font-body);
285:   font-size: 0.8125rem;
286:   color: var(--wx-text-faint);
287: }
288: 
289: .wx-atlas__grid {
290:   display: grid;
291:   grid-template-columns: repeat(auto-fit, minmax(9.5rem, 1fr));
292:   gap: 10px;
293:   list-style: none;
294:   margin: 0;
295:   padding: 0;
296: }
297: 
298: .wx-atlas__cell {
299:   display: flex;
300:   flex-direction: column;
301:   gap: 3px;
302:   min-height: 44px;
303:   padding: 10px 12px;
304:   text-align: left;
305:   font-family: var(--wx-font-body);
306:   color: var(--wx-parchment);
307:   background: var(--wx-clear-soft);
308:   border: 1px solid var(--wx-rule);
309:   border-top-width: 5px;
310:   border-radius: var(--wx-radius);
311: }
312: 
313: button.wx-atlas__cell {
314:   cursor: pointer;
315: }
316: 
317: .wx-atlas__cell-clear {
318:   background: var(--wx-clear-soft);
319:   border-top-color: var(--wx-clear);
320: }
321: 
322: .wx-atlas__cell-cloudy {
323:   background: var(--wx-cloudy-soft);
324:   border-top-color: var(--wx-cloudy);
325: }
326: 
327: .wx-atlas__cell-overcast {
328:   background: var(--wx-overcast-soft);
329:   border-top-color: var(--wx-overcast);
330: }
331: 
332: .wx-atlas__cell-rain {
333:   background: var(--wx-rain-soft);
334:   border-top-color: var(--wx-rain);
335: }
336: 
337: .wx-atlas__cell-drought {
338:   background: var(--wx-drought-soft);
339:   border-top-color: var(--wx-drought);
340: }
341: 
342: .wx-atlas__cell-storm {
343:   background: var(--wx-storm-soft);
344:   border-top-color: var(--wx-storm);
345: }
346: 
347: .wx-atlas__cell-flood {
348:   background: var(--wx-flood-soft);
349:   border-top-color: var(--wx-flood);
350: }
351: 
352: .wx-atlas__cell-selected {
353:   box-shadow: inset 0 0 0 2px var(--wx-parchment);
354: }
355: 
356: .wx-atlas__state {
357:   font-family: var(--wx-font-display);
358:   font-size: 0.6875rem;
359:   letter-spacing: 0.1em;
360:   text-transform: uppercase;
361:   color: var(--wx-text-dim);
362: }
363: 
364: .wx-atlas__count {
365:   font-family: var(--wx-font-display);
366:   font-size: 1.5rem;
367:   font-weight: 700;
368:   line-height: 1.1;
369:   font-variant-numeric: tabular-nums;
370: }
371: 
372: .wx-atlas__percent {
373:   font-family: var(--wx-font-body);
374:   font-size: 0.75rem;
375:   color: var(--wx-text-dim);
376:   font-variant-numeric: tabular-nums;
377: }
378: 
379: /* ==========================================================================
380:    Motion: strip tiles settle in, the cliff line draws down. Only when
381:    motion is welcome; the global prefers-reduced-motion: reduce block in
382:    src/index.css zeroes every animation duration as well.
383:    ========================================================================== */
384: 
385: @media (prefers-reduced-motion: no-preference) {
386:   .wx-strip__tile {
387:     animation: wx-fade 380ms ease-out backwards;
388:     /* The per tile stagger arrives as an inline animation-delay from
389:        ForecastStrip, which wins over this class shorthand. */
390:   }
391: 
392:   .wx-cliff {
393:     animation: wx-fade 480ms ease-out backwards;
394:   }
395: }
396: 
397: @keyframes wx-fade {
398:   from {
399:     opacity: 0;
400:   }
401: 
402:   to {
403:     opacity: 1;
404:   }
405: }

